# char_name 可能是这两个值中的任何一个: CharFactory.py:120 把 char_linnai 和
# char_linnai2 映射到同一个类。原版这里写的是 != 'char_linnai', 换个立绘就恒真
LINNAI_NAMES = {'char_linnai', 'char_linnai2'}
AEMEATH_NAMES = {'char_aemeath'}


# ==================== 自动战斗开关监视 ====================
# 【玩家手动开关自动战斗, 必须从启动轴重跑】。手动停任务不走 combat_end(), opener_armed 会跨局留在
# False, 而角色对象常被粘性复用、reset_state() 不跑。只有独立线程能观察到 enabled 的 True->False->True。
# 跟 skill 参考队伍 Hsin__Rover__Suisui/Hsin.py 里那份逐字相同。
ENABLE_POLL_INTERVAL = 0.2


def start_enable_watch(task, logger=None):
    """盯 task.enabled 的 False->True 跳变, 把时刻记到 task._ww_task_restarted_at。每个 task 只启一次。"""
    if getattr(task, '_ww_enable_watch_started', False):
        return
    task._ww_enable_watch_started = True
    if not hasattr(task, '_ww_task_restarted_at'):
        task._ww_task_restarted_at = -1

    def watch():
        was_on = None
        while True:
            try:
                now_on = bool(getattr(task, 'enabled', False))
                if was_on is False and now_on:
                    task._ww_task_restarted_at = time.time()
                    if logger:
                        logger.info('auto combat re-enabled -> opener re-armed')
                was_on = now_on
                time.sleep(ENABLE_POLL_INTERVAL)
            except Exception:
                return

    threading.Thread(target=watch, name='ok_ww_enable_watch', daemon=True).start()


class Mornye(NativeMornye):
    """莫宁。爱琳莫队里她还兼任启动轴的驱动者。

    启动轴是一条跨三个角色的线性宏, 只能放在一个文件里 —— 自定义角色文件由
    CustomCharLoader 按路径单独加载, 互相 import 不到。按键是全局的, 谁在场就是谁
    在打, 所以由谁持宏无所谓, 挑了轴上第一个上场的莫宁。

    现役是第六版(OPENER_VERSION = 6, 2026-10-11, 视频「爱琳莫轮椅15s启动轴」, 6 链爱弥斯 + 专武莫宁):

      SEG1  莫宁 A1A2 -> 琳奈[A1] E -> 莫宁[A3] 按住升空 -> 升空途中切琳奈 R
            -> 演出里点派生A + 连按切人 -> 莫宁回场空中 R(打断升空后摇, 视频最后那段的"后置莫宁R")
      SEG2  莫宁 R 演完 空中A123 + E + 天基炮 -> 等协奏满 -> 变奏琳奈 E -> 爱弥斯 A到A4 + E(进机甲)
            -> 按住切琳奈 蓄力到 2 级 -> 两段踢补满协奏 -> 变奏爱弥斯 跳
      收尾  爱弥斯 R1 -> 演出里按住出一链炮 -> 重击收尾连按 F 处决 -> 光翼 -> A2A3A4
            -> 光翼 + 重击 -> R2 -> 进机甲(循环轴入口), 见 Aemeath.perform_v6_opener_burst
      为什么这么打: 琳奈开场 A1+E、变奏 +100 攒够 120 溢彩才能蓄力; 莫宁 A1/A2/A3 第 1F 各给
      20/43/37 回路(A3 一出手就 100), 接着按住就是位势转换; 莫宁 R 可以空中放, 用它打断升空后摇,
      R 演完她已经在观测模式里, 直接接空中 A; 爱弥斯 R1 给"大招2解锁前置", 一链速蓄的
      强化重击直接给 200 同步率, 两发光翼各 -100 同步率 +1 共鸣率, R1(带流光增幅)+2 光翼 = 4 共鸣率
      -> R2。处决放在第一发光翼之前, 两发光翼都吃得到处决带来的轨迹(慢一个 A2 约 0.6s)。
      循环轴: LOOP_VERSION = 2 走 perform_loop_v2(视频「后置琳奈下砸23s双变循环轴」, 逐格见那里),
      = 1 走下面第四版那套。R2 后不回框架, l2_loop_chain 一圈接一圈。
      循环轴保底(2.0.0 定稿): 莫宁 A12 读地面回路条攒到 0.58 才切(被挤上怪顶打成 A1+A3 就多点一下);
      莫宁空中 E 后 0.45s 连发 R 不读"能不能放"(对视频: R 出手时 E 冷却 15.4), R 演出里就按住出天基炮;
      琳奈 R 能量不够边 A 边按 R, 4s 放不出跳过这圈; 中途玩家自己按 R 也认, 等演出完再接。

    第四版轴(用户 2026-08-13 提供的图):

      SEG1  琳奈E -> 莫宁 A到A3 + R(打断A3) + 演出中预输入重击(起飞)
            -> 起飞瞬间切琳奈 R + 演出中点普攻(打派生)
      SEG2  切莫宁 空中A×3 + E + 强化重击 -> 变奏琳奈
      SEG3  琳奈 蓄力重击 -> 出伤 -> 跳跃(特殊攻击补协奏) -> 变奏爱弥斯
            -> 交还爱弥斯, 走她自己的收尾爆发

    【和第三版最大的差别: 爱弥斯在启动轴里完全不上场】(用户 2026-08-13 确认),
    只在最后变奏进来打爆发。v3 里她那三段(开场 A1A2A3、琳奈R后的 [A4]、
    SEG2 的 Q+A到A4+后撤E)全部删掉了 —— 那是 v3 最贵的一块。

    "切人自带的那一下普攻"是框架行为: BaseCombatTask.py:644 在每次发数字键之后
    紧跟一次 self.click()。这里自己发, 所以哪几次带、哪几次不带是可控的。
    """

