    # 切人那刻稳定读到 con0.96~0.99, 缺口就是最后 1~2%
    # 【纯等待这条路走不通, 别再试】: 0 / 0.10 / 0.17 / 0.25 / 0.35 全部掉变奏,
    # 切人那刻始终停在 con0.96~0.99。唯一成功过的 0.15 那轮是 SEG3_PRECHARGE 还没修、
