    # 【结论: 最后 1~2% 必须打出来, 不是等出来的】—— 同一个形状今天出现三次
    # (莫宁A段的补点 / SEG2 的 wait_con_for_intro / 这里)
    SEG3_JUMP_SWITCH_DELAY = 0.35
    M_LIN_JUMP_SETTLE = 0.15
    # 跳跃之后再过多久才允许补点(相对 M_LIN_JUMP_SETTLE 之后, 两个加起来 = 原来的 0.45)。
    # 【拆成两个数是有原因的】: 0.45 那个版本同时在管"别太早读"和"别太早点",
    # 而这两件事的成本完全不同 —— 读屏单次 0.01~0.02 秒, 白读几乎不要钱;
    # 补点则可能打断这一跳自己的特殊攻击。日志(2026-08-14, 14 轮成功)显示
    # 【5 轮在第一次采样就读到 1.00】, 那几轮的 0.45 全是白等
    # 【0.30 -> 0.05】(2026-08-14): 原来推迟补点是怕那一下点击打断这一跳自己的
    # 特殊攻击。直切实验顺带证伪了这个顾虑 —— charge_up 时协奏 0.83, 跳后 0.15 秒
    # 就读到 0.96~0.99, 【那一跳的伤害在 0.15 秒内已经结算完】, 之后再点打断不了。
    # 而缺的最后 1~2% 只能靠补点打上去(纯等待 0/0.10/0.17/0.25/0.35 全部掉变奏),
    # 所以补点越早交棒越早
    M_LIN_POKE_AFTER = 0.05
    # 琳奈变奏入场 -> 开始蓄力。v3 里这个值是"变奏入场出伤"的等待, 含义没变
    # 变奏琳奈入场那一格要不要连发 E。V3 原版是纯等出伤(注释还写着"这里的E是
    # 爱弥斯的"), 用户 2026-08-14 实机确认 E 不会打断她的变奏, 于是改成边等边发
    # 启动轴要不要给爱弥斯放声骸 Q。用户 2026-08-14: "不要放了, 好像会延迟输入,
    # 虽然不打断动作" —— 原注释以为"Q 不会打断动作所以放在开头最省", 但不打断
    # 不等于不占时间
    # 空中段顺路采样回路条。【已经验过, 别再开】(2026-08-14):
    #   air forte: 0.14:1 0.42:0 0.69:0 0.97:0 1.25:0 1.54:0 1.82:0 | preE:0
    # 开头那个 1 是【假的】—— 回路条读数滞后约 0.8 秒, 0.14 秒读到的还是升空重击
    # 之前的状态; 之后全程 0。所以这段【确实没有任何可用判据】, 别再想着加锚点。
    # 而且它【会挤掉点击】: 开采样那轮 airA_end 从 x15 掉到 x14, 空中 A 少打一段,
