    # 无关 —— 要连它一起省得单独说。
    # 2026-08-14: 加回来试过一轮, 用户又去掉了。窗口 1.20 那个时间点是对的,
    # 但这一格不放 E
    SEG2_AEM_E = True
    # 切琳奈【之前】就按住鼠标, 让"按下沿=一下普攻"落在离场的爱弥斯身上
    V3_PRECHARGE = True
    V3_LIN_INTRO_E = True
    # 变奏琳奈那一格, 最后一发 E 到切人键之间留多久。
    # 【不能共用 M_LIN_E_TO_SWITCH】: 那个是 V4 开场用的(琳奈战斗一开始就站在场上,
    # 没有入场动画挡着), 今天刚标定成 0.15, 动它会把 V4 一起改掉。
    # 这一格的处境不同 —— 她是【变奏入场】进来的, 前几发 E 要先被入场动画吃掉,
