    # 0.60 -> 0.40 (0.23 试过, E 按不出来, 已退回)。
    # 【这一格没有余量, 别再砍】(2026-08-14): 变奏入场动画约 0.9 秒, E 只能在它
    # 之后才成立 —— 窗口 0.23 时那 2~3 发全被吃掉。连发窗口 + 尾巴 = 0.65 是
    # 实测能用的组合(用户当时确认"琳奈E放出来了, 这个时间可以")
    M_LIN_INTRO_E_WINDOW = 0.40
    # 0.25 -> 0.08(用户 2026-08-14 逐帧: E 进 CD 之后又过了 0.19 秒才切小爱,
    # 那段是多余的)。
    # 【上一次我砍错了地方】: 用户说"切小爱减 0.17", 我从连发窗口里扣, 结果 E
    # 根本没成立(窗口 0.23 时那几发全被入场动画吃掉)。砍窗口 = 让 E 更难出手;
    # 砍尾巴 = E 照常出手, 只是出手后早点走
    # 0.25 -> 0.10(用户 2026-08-14 逐帧: 还能再快 0.15, "按了E就疯狂切爱弥斯")。
    # 【切人本身就是连发的】: quick_switch 每 SWITCH_KEY_INTERVAL 重发一次切人键
