    M_LIN_INTRO_E_TO_SWITCH = 0.10
    M_LIN_INTRO_DAMAGE = 0.60
    SEG2_STEP_SETTLE = 0.15
    # 开场琳奈 E 发出去 -> 发切莫宁的数字键。
    #
    # 【0 是 v3 的值, 那时她是被切进来的】: E 是预输入, "E 和切人键同时发"才对 ——
    # 切人本身要 0.06~0.11 才落地, 那时她还在场上, E 照样生效, 等 E 生效再切是白等。
    # 【但 v4 她开局就站在场上, E 是立刻发出去的实招】, 同一个 0 就变成"刚起手
    # 就被切走": 用户 2026-08-13 实机"切人切得有点快把E卡没了, 虽然E依旧按下去了"。
    # 时间轴对照: linE(onfield)@0.01 -> >Mor@0.11, 中间只有 0.10 秒。
    # 【同一个常量在两条路径上语义不同 —— 这既是它被设成 0 的原因, 也是它出问题的原因】
    #
    # 【这是 E 键发出去【之后】的一段干等, 不是"E 的动画时间"】——
    # send_resonance_key() 早就返回了, 这段时间琳奈站着不动。用户 2026-08-13 纠正:
    # "0.3 不是E的时间, 是琳奈e切莫宁中间的停顿"。所以它跟 F_START_DELAY 是同一种
    # 东西(纯等), 只是等的位置不同 —— 别再拿"这里是白赚的"当理由把它调大。
    #
    # 它现在同时承担两件事: 给 E 留够时间别被切人卡掉 + 吸收 F 启动带来的刷怪延迟。
    # 【一个值扛两个职责就必然又慢又脆】, 这一点上它和当初那个既当"平均等待"
    # 又当"最坏保险"的固定值是同一个毛病 —— 拆开的办法见下面那段"别再往上加数"。
    #
    # 标定过程: 0(v3 值, 那时琳奈是被切进来的、E 是预输入) -> 0.10 E 被卡掉
    #   -> 0.30 用户嫌久(那一版 F 延迟还是 0.15, 两处在重复等同一件事)
    #   -> 0.15 -> 0.30(F 延迟归零, 等待集中到这里, 实机可用但"不够极限")
    #   -> 0.15 E 打空了 -> 0.20 <- 当前(在 0.15✗ / 0.30✓ 之间二分)
    #
    # 【琳奈的 E 要打到怪才给能量条】(用户 2026-08-13), 所以它不是不接触的动作。
    # 【而这个常量确实决定 E 的伤害落不落得下来】——【切人会把 E 剩下的动作取消掉】,
    # 伤害是在动作途中才结算的。所以多留她一会儿的意义不是"等 E 演完好看",
    # 而是【让 E 的伤害窗口去接怪的刷新】: 怪在 E 动作途中刷出来, 伤害就接上了,
    # 接上一点能量就够(用户原话)。
    # (我一度说过"改它只挪切人时刻、挪不动 E", 那是错的 —— 挪不动 E 的【发出】时刻,
    #  但挪得动 E 的【被取消】时刻, 而伤害在两者之间)
    #
    # 【要是 E 还是被卡掉, 别再往上加数】: 那说明输入压根没被接受(她还在按 F 的
